surfaceVertex:
#version 300 es
layout(location = 0) in vec3 position;
layout(location = 1) in vec3 normal;
layout(location = 2) in vec2 uv;

uniform mat4 viewProjection;
uniform mat4 model;
uniform float time;
uniform float u_gain;
out vec2 v_uv;

void main() {
  v_uv = uv;
  float n2 = u_gain;
  float n11 = time;
  float n12 = (n11 * n2);
  float n13 = sin(n12);
  vec3 n18 = normal;
  float n19 = 0.25;
  float n20 = (n13 * n19);
  vec3 n21 = (n18 * n20);
  gl_Position = viewProjection * model * vec4(position + n21, 1.0);
}

surfaceFragment:
#version 300 es
precision highp float;

in vec2 v_uv;
uniform float opacity;
uniform float time;
uniform vec4 u_tint;
uniform float u_gain;
uniform vec4 u_offset;
uniform vec3 u_axis;
uniform mat4 u_spin;
uniform mat4 u_warp;
uniform sampler2D s_map;

out vec4 fragColor;

void main() {
  vec2 n0 = v_uv;
  vec4 n1 = u_tint;
  float n2 = u_gain;
  vec2 n3 = u_offset.xy;
  vec3 n4 = u_axis;
  mat3 n5 = mat3(u_spin);
  mat4 n6 = u_warp;
  vec2 n7 = (n0 + n3);
  vec4 n8 = texture(s_map, n7);
  vec3 n9 = (n5 * n4);
  vec4 n10 = (n6 * n1);
  float n11 = time;
  float n12 = (n11 * n2);
  float n13 = sin(n12);
  vec4 n14 = (n8 * n10);
  vec4 n15 = vec4(n9, n13);
  vec4 n16 = (n14 + n15);
  vec4 n17 = clamp(n16, 0.0, 1.0);
  vec4 c = n17;
  fragColor = vec4(c.rgb, c.a * opacity);
}

screenVertex:
#version 300 es
out vec2 v_uv;

void main() {
  v_uv = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  gl_Position = vec4(v_uv * 2.0 - 1.0, 0.0, 1.0);
}

screenFragment:
#version 300 es
precision highp float;

in vec2 v_uv;
uniform float u_gain;
uniform sampler2D s_source;

out vec4 fragColor;

void main() {
  vec2 n0 = v_uv;
  vec4 n1 = texture(s_source, n0);
  float n2 = u_gain;
  vec3 n3 = n1.xyz;
  vec3 n4 = (n3 * n2);
  float n5 = n1.w;
  vec4 n6 = vec4(n4, n5);
  fragColor = n6;
}
